174: class _AppLocalizationsDelegate
175:     extends LocalizationsDelegate<AppLocalizations> {
176:   const _AppLocalizationsDelegate();
177: 
178:   @override
179:   Future<AppLocalizations> load(Locale locale) {
180:     return SynchronousFuture<AppLocalizations>(lookupAppLocalizations(locale));
181:   }
182: 
183:   @override
184:   bool isSupported(Locale locale) =>
185:       <String>['en', 'ru'].contains(locale.languageCode);
186: 
187:   @override
188:   bool shouldReload(_AppLocalizationsDelegate old) => false;
189: }
190: 
191: AppLocalizations lookupAppLocalizations(Locale locale) {
192:   // Lookup logic when only language code is specified.
193:   switch (locale.languageCode) {
194:     case 'en':
195:       return AppLocalizationsEn();
196:     case 'ru':
197:       return AppLocalizationsRu();
198:   }
199: 
200:   throw FlutterError(
201:     'AppLocalizations.delegate failed to load unsupported locale "$locale". This is likely '
202:     'an issue with the localizations generation tool. Please file an issue '
203:     'on GitHub with a reproducible sample app and the gen-l10n configuration '
204:     'that was used.',
205:   );
206: }

