class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> with SingleTickerProviderStateMixin {
  int _selectedIndex = 0;

  late final List<Widget> _pages;

  final GlobalKey<CurrencyListPageState> _currencyKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsKey = GlobalKey();

  @override
  void initState() {
    super.initState();
    _pages = <Widget>[
      CurrencyListPage(key: _currencyKey),
      NewsListPage(key: _newsKey),
      ProfilePage(),
    ];
  }

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> _refreshAll() async {
    final CurrencyRepository currencyRepo = context.read<CurrencyRepository>();
    final NewsRepository newsRepo = context.read<NewsRepository>();
    final AppLocalizations loc = context.loc;

    try {
      await Future.wait(<Future<dynamic>>[
        currencyRepo.fetchRates(const CurrencyPageRequest()),
        newsRepo.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
      ]);
      _currencyKey.currentState?.refresh();
      _newsKey.currentState?.refresh();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(loc.refreshAll)),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.currencyRate)),
      body: currentPage,
      floatingActionButton: FloatingActionButton(
        onPressed: _refreshAll,
        child: const Icon(Icons.refresh),
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: <BottomNavigationBarItem>[
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            BottomNavigationBarItem(
              icon: const Icon(Icons.person),
              label: loc.profile,
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
